package database

// postgresSchema is application-owned and immutable once first deployed.
// SQLite remains the current production backend. No automatic cutover occurs.
// Existing tables are not silently adopted. clients.updated_at remains nullable
// because older SQLite upgrades added that column without historical values.
const postgresSchema = `CREATE TABLE users (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, username TEXT NOT NULL UNIQUE, display_name TEXT NOT NULL, directory_dn TEXT NOT NULL DEFAULT '', pin_hash TEXT NOT NULL DEFAULT '', oidc_subject TEXT NOT NULL DEFAULT '', created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE badges (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, badge_code TEXT NOT NULL UNIQUE, user_id BIGINT NOT NULL REFERENCES users(id), token_hash TEXT NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, description TEXT NOT NULL DEFAULT '', issued_by TEXT NOT NULL DEFAULT '', created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, last_used_at TIMESTAMPTZ, revoked_at TIMESTAMPTZ);
CREATE TABLE audit_log (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, event_type TEXT NOT NULL, badge_id TEXT NOT NULL DEFAULT '', username TEXT NOT NULL DEFAULT '', client_id TEXT NOT NULL DEFAULT '', success BOOLEAN NOT NULL, ip_address TEXT NOT NULL DEFAULT '', timestamp TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, details TEXT NOT NULL DEFAULT '');
CREATE TABLE clients (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, client_id TEXT NOT NULL UNIQUE, token_hash TEXT NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, version TEXT NOT NULL DEFAULT '', network_status TEXT NOT NULL DEFAULT 'unknown', ad_status TEXT NOT NULL DEFAULT 'unknown', camera_status TEXT NOT NULL DEFAULT 'unknown', kerberos_status TEXT NOT NULL DEFAULT 'unknown', last_update_version TEXT NOT NULL DEFAULT '', last_update_status TEXT NOT NULL DEFAULT 'unknown', last_update_at TIMESTAMPTZ, rollback_available BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP, last_seen_at TIMESTAMPTZ);
CREATE TABLE self_service_sessions (id TEXT PRIMARY KEY, username TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, expires_at TIMESTAMPTZ NOT NULL, revoked_at TIMESTAMPTZ);
CREATE TABLE oidc_clients (client_id TEXT PRIMARY KEY, secret_hash TEXT NOT NULL, redirect_uris TEXT NOT NULL, scopes TEXT NOT NULL DEFAULT 'openid', enabled BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE oidc_codes (code_hash TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES oidc_clients(client_id), user_id BIGINT NOT NULL REFERENCES users(id), redirect_uri TEXT NOT NULL, scope TEXT NOT NULL, nonce TEXT NOT NULL, code_challenge TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, expires_at TIMESTAMPTZ NOT NULL, consumed_at TIMESTAMPTZ);
CREATE INDEX idx_badges_code ON badges(badge_code); CREATE INDEX idx_audit_timestamp ON audit_log(timestamp); CREATE INDEX idx_clients_last_seen ON clients(last_seen_at);
ALTER TABLE badges ADD COLUMN activation_pending BOOLEAN NOT NULL DEFAULT FALSE;
CREATE UNIQUE INDEX idx_users_oidc_subject ON users(oidc_subject) WHERE oidc_subject<>'';
CREATE INDEX idx_oidc_codes_expiry ON oidc_codes(expires_at);
`

const postgresOIDCSessionsMigration = `CREATE TABLE oidc_sessions (session_id TEXT PRIMARY KEY, access_token_hash TEXT NOT NULL UNIQUE, client_id TEXT NOT NULL REFERENCES oidc_clients(client_id), user_id BIGINT NOT NULL REFERENCES users(id), scope TEXT NOT NULL, issued_at TIMESTAMPTZ NOT NULL, expires_at TIMESTAMPTZ NOT NULL, revoked_at TIMESTAMPTZ);
CREATE INDEX idx_oidc_sessions_expiry ON oidc_sessions(expires_at);
CREATE INDEX idx_oidc_sessions_user ON oidc_sessions(user_id,issued_at);`

const postgresWebAuthnMigration = `CREATE TABLE webauthn_users (user_id BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, user_handle BYTEA NOT NULL UNIQUE CHECK(octet_length(user_handle) BETWEEN 32 AND 64), created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE webauthn_credentials (credential_id BYTEA PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES webauthn_users(user_id) ON DELETE CASCADE, public_key BYTEA NOT NULL, rp_id TEXT NOT NULL, name TEXT NOT NULL, transports TEXT NOT NULL DEFAULT '', attestation_type TEXT NOT NULL DEFAULT '', attestation_format TEXT NOT NULL DEFAULT '', flags INTEGER NOT NULL DEFAULT 0, sign_count BIGINT NOT NULL DEFAULT 0 CHECK(sign_count>=0), backup_eligible BOOLEAN NOT NULL DEFAULT FALSE, backup_state BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, last_used_at TIMESTAMPTZ, revoked_at TIMESTAMPTZ);
CREATE TABLE webauthn_ceremonies (id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('registration','authentication')), audience TEXT NOT NULL CHECK(audience IN ('self-service','admin')), user_id BIGINT REFERENCES users(id) ON DELETE CASCADE, session_data BYTEA NOT NULL CHECK(octet_length(session_data) BETWEEN 1 AND 65536), created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, expires_at TIMESTAMPTZ NOT NULL, consumed_at TIMESTAMPTZ);
CREATE INDEX idx_webauthn_credentials_user ON webauthn_credentials(user_id,created_at);
CREATE INDEX idx_webauthn_ceremonies_expiry ON webauthn_ceremonies(expires_at);`

const postgresWebAuthnManagementMigration = `ALTER TABLE webauthn_credentials ADD COLUMN management_id TEXT;
UPDATE webauthn_credentials SET management_id=gen_random_uuid()::text WHERE management_id IS NULL;
ALTER TABLE webauthn_credentials ALTER COLUMN management_id SET NOT NULL;
ALTER TABLE webauthn_credentials ADD CONSTRAINT webauthn_management_id_length CHECK(length(management_id) BETWEEN 16 AND 128);
CREATE UNIQUE INDEX idx_webauthn_credentials_management ON webauthn_credentials(management_id);`
